<script setup>import {computed,ref} from 'vue';import {state,actions,displayTime} from '../../domain/prototypeStore.js';const text=ref('');const mine=computed(()=>state.events.filter(e=>e.createdBy===state.user.name||state.user.role==='应急指挥人员'));const submit=i=>{actions.addUpdate(i,text.value);text.value=''}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>事</span><h2>我的事件</h2><p>查看处理进度并提交现场续报</p></div><article v-for="e in mine" :key="e.id" class="h5-card"><header><strong>{{e.title}}</strong><span>{{e.status}}</span></header><small>{{displayTime(e.createdAt)}} · {{e.location}}</small><p>{{e.timeline.at(-1)?.label}}：{{e.timeline.at(-1)?.detail}}</p><input v-model="text" placeholder="补充现场情况"><button class="secondary-button" @click="submit(e.id)">提交续报</button></article></section></template>
